link.script:
	var instagramClient, instagramToken, instagramItems;
	function init() {
		window.addEventListener('scroll', function(e){
			var distanceY = window.pageYOffset || document.documentElement.scrollTop,
				shrinkOn = 300;
			header = document.querySelector("header");
			if (distanceY > shrinkOn) {
				classie.add(header,"smaller");
			} else {
				if (classie.has(header,"smaller")) {
					classie.remove(header,"smaller");
				}
			}
		});
	}
	window.onload = init(); 

	/* Top links fading in/out

            if ($(window).width() < 760){


            $(window).scroll(function() {  

            if ($(this).scrollTop()>0)
             {
                $('.top_links').fadeOut();
             }
            else
             {
              $('.top_links').fadeIn();
             }
            });


            }

            */

	if ($(window).width() < 760){

		$(document).ready(function(){   
			$(window).scroll(function () {
				if ($(this).scrollTop() > 50) {
					$('#back-to-top').fadeIn();
				} else {
					$('#back-to-top').fadeOut();
				}
			});
			// scroll body to 0px on click
			$('#back-to-top').click(function () {
				$('#back-to-top').tooltip('hide');
				$('body,html').animate({
					scrollTop: 0
				}, 800);
				return false;
			});

			$('#back-to-top').tooltip('show');

		});
	}

(function() {
    // Exclusion path(s)
    var excludedPaths = ['/pf/default.aspx', '/pf', '/pf/'];
    var currentPath = window.location.pathname;

    // Normalize the path (for comparison)
    var normalizedPath = currentPath.replace(/\/$/, '');

    // Is it on 'thelist' ?
    var isExcluded = excludedPaths.some(function(path) {
        return normalizedPath === path.replace(/\/$/, '');
    });

if (isExcluded) {
    console.log('Script suppressed for path:', currentPath);

    // Remove the call racker
    var existing = document.querySelector('script[src*="pbsc-jomar-swap.js"]');
    if (existing) {
        existing.parentNode.removeChild(existing);
        console.log('Removed pbsc-jomar-swap.js that was globally injected.');
    }

    // Block Google Analytics (gtag.js)
    var gaScript = document.querySelector('script[src*="gtag/js"]');
    if (gaScript) {
        gaScript.parentNode.removeChild(gaScript);
        console.log('Removed Google Analytics gtag.js script.');
    }

    // Block GTM  (gtm.js)
    var gtmScript = document.querySelector('script[src*="gtm.js"]');
    if (gtmScript) {
        gtmScript.parentNode.removeChild(gtmScript);
        console.log('Removed Google Tag Manager script.');
    }

    // Neautralize GA if it's loaded
    window.dataLayer = [];
    window.gtag = function(){ console.log("GA blocked on this path:", currentPath); };
}

})();

